expect.check:
expected = {f'{run}-P1': ('FZERHIULMFGESH-UHFFFAOYSA-N', 1.5), f'{run}-P2': ('RWCCWEUUXYIKHB-UHFFFAOYSA-N', 0.75), f'{run}-P3': ('BTJIUGUIPKRLHP-UHFFFAOYSA-N', 0.2)}
problems = []
samples = collection.get_samples(per_page=100)
for label, (key, grams) in expected.items():
    found = [s for s in samples if s.properties.get('external_label') == label]
    if len(found) != 1:
        problems.append(f'{label}: {len(found)} samples')
        continue
    s = found[0]
    if s.molecule.get('inchikey') != key:
        problems.append(f"{label}: InChIKey {s.molecule.get('inchikey')}")
    if s.gram is None or abs(s.gram - grams) > 1e-6:
        problems.append(f'{label}: {s.gram} g')
result = True if not problems else '; '.join(problems)

